  "name": "rf_core_mode_check",
  "confidence": "medium",
  "docstring": "Checks an RF/PHY core-mode and channel table configuration, returning 1 for bypass/error-like cases and returning 0 only when the selected channel entry has mode byte 1 but its low two flag bits are clear, in which case it sets bit 0x1000 in the context flag word.",
  "subsystem": "rf",
  "var_renames": {
    "v1": "channel_idx",
    "v2": "channel_entry",
    "v3": "result"
  },
  "struct_hints": [
    {
      "offset": 28,
      "meaning": "core-mode table index"
    },
    {
      "offset": 29,
      "meaning": "channel table index"
    },
    {
      "offset": 30,
      "meaning": "context flag word; bit 0x1000 is set when the selected channel entry has no low mode-flag bits set"
    }
  ]
}
